L000031	\title{Spontaneous Ratchet Currents and Transition Dynamics in Active Wetting}
L000032	
L000033	\author{Noah Grodzinski$^{1}$}\thanks{Corresponding author: njbg2@cam.ac.uk (he/him)}
L000034	\author{Robert L. Jack$^{1,2}$}
L000035	\author{Michael E. Cates$^{1}$}
L000036	
L000037	\affiliation{$^1$Department of Applied Mathematics and Theoretical Physics, University of Cambridge, Wilberforce Road, Cambridge, United Kingdom}
