L000211	\section{APPENDIX}
L000212	\subsection{Derivation of the Ratchet Current}\label{app:ratchet_current}
L000213	We derive \eqref{eq:SS_current} for the steady state density current, working from the dimensionless dynamics (\ref{eq:ABP_evolution}). We start from the expression for the spatial probability current in (\ref{eq:J_diff}, \ref{eq:J_act}), for which only the x-component is non-vanishing:
L000214	\begin{multline}
L000215	  J_x(x, \theta) = - \left[ d_s(\rho) \partial_x f + f \mathcal{D}(\rho) \partial_x \rho + (1-\rho) f \partial_x V \right] \\ + \text{Pe} \left[  (\mathcal{D}(\rho)-1) f p_x + \cos(\theta) f d_s(\rho) \right] \;
L000216	\end{multline}
L000217	Integrating over $\theta$ and making use of the definition of $\mathcal{D}(\rho)$, we obtain the spatial density current
L000218	\begin{equation}
L000219	    J^{(\rho)} =  -\left[ \partial_x \rho + (1-\rho)\rho \partial_x V \right] + \text{Pe} (1-\rho) p_x \label{eq:appendix_density_current}
L000220	\end{equation}
L000221	
L000222	In steady state, the density current must be divergence-free, and so its one non-vanishing component must be a constant $J^{(\rho)}(x) = J^{(\rho)}_{\text{ss}}$. Dividing (\ref{eq:appendix_density_current}) through by $1-\rho$, integrating over space with periodic boundaries, and using the identity $\int_0^{\ell_s} \vb{p} \ \dd x = 0$ in steady-state\footnote{Orientational dynamics is independent of position, so the total polarisation must generically vanish. This can be proven easily from the dynamics.}, yields:
L000223	\begin{equation}
L000224	   J^{(\rho)}_{\text{ss}} = M[\rho] \int_0^{\ell_s} V(x) \, \partial_x \rho \dd{x} \;
L000225	   \label{equ:J-MM-parts}
L000226	\end{equation}
L000227	where $M[\rho] = [ \int_0^{\ell_s} \frac{1}{(1-\rho)} \dd x]^{-1}$.  Integration by parts on \eqref{equ:J-MM-parts} yields \eqref{eq:SS_current}.
